function randomCharacterName(excluded=[]){
  const used=new Set(excluded.filter(Boolean).map(name=>String(name).trim().toLocaleLowerCase()));
  const combinations=CHARACTER_FIRST_NAMES.length*CHARACTER_LAST_NAMES.length;
  const start=Math.floor(Math.random()*combinations);
  for(let offset=0;offset<combinations;offset++){
    const index=(start+offset)%combinations;
    const name=`${CHARACTER_FIRST_NAMES[index%CHARACTER_FIRST_NAMES.length]} ${CHARACTER_LAST_NAMES[Math.floor(index/CHARACTER_FIRST_NAMES.length)]}`;
    if(!used.has(name.toLocaleLowerCase()))return name;
  }
  const first=CHARACTER_FIRST_NAMES[Math.floor(Math.random()*CHARACTER_FIRST_NAMES.length)];
  const last=CHARACTER_LAST_NAMES[Math.floor(Math.random()*CHARACTER_LAST_NAMES.length)];
  for(let suffix=2;;suffix++){const name=`${first} ${last} ${suffix}`;if(!used.has(name.toLocaleLowerCase()))return name}
}
