function randomItem(items){return items[Math.floor(Math.random()*items.length)]}
function shuffle(items){for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}return items}
function rollAbilityScore(){const dice=Array.from({length:4},()=>Rules5e.rollDie(6));return dice.sort((a,b)=>b-a).slice(0,3).reduce((sum,die)=>sum+die,0)}
function createRandomCharacter({id=uid('char'),ownerPlayerId=null,location='Lantern Room',nameExclusions=[],notes=''}={}){
  const className=randomItem(Object.keys(CHARACTER_CLASSES)),classData=CHARACTER_CLASSES[className];
  const species=randomItem(CHARACTER_SPECIES),background=randomItem(CHARACTER_BACKGROUNDS),subclass=randomItem(CHARACTER_SUBCLASSES[className]||['']),abilityKeys=['str','dex','con','int','wis','cha'];
  const scores=shuffle(Array.from({length:6},rollAbilityScore)),abilities=Object.fromEntries(abilityKeys.map((key,index)=>[key,scores[index]]));
  Object.entries(species.bonuses).forEach(([key,bonus])=>abilities[key]+=bonus);
  if(species.chooseTwoBonuses)shuffle(abilityKeys.filter(key=>key!=='cha')).slice(0,2).forEach(key=>abilities[key]++);
  const backgroundSkills=[...background.skills];
  const skillOptions=(classData.skills||Object.keys(CHARACTER_DEFAULTS.skills)).filter(key=>!backgroundSkills.includes(key));
  const classSkills=shuffle(skillOptions).slice(0,classData.skillCount);
  const skills={...CHARACTER_DEFAULTS.skills};
  [...backgroundSkills,...classSkills].forEach(key=>skills[key]=true);
  if(species.chooseTwoSkills)shuffle(Object.keys(skills).filter(key=>!skills[key])).slice(0,2).forEach(key=>skills[key]=true);
  const saves={...CHARACTER_DEFAULTS.saves};
  classData.saves.forEach(key=>saves[key]=true);
  const constitutionModifier=abilityModifier(abilities.con),dexterityModifier=abilityModifier(abilities.dex),wisdomModifier=abilityModifier(abilities.wis);
  const draconicOrigin=className==='Sorcerer'&&subclass==='Draconic Bloodline';
  const hitPoints=Math.max(1,classData.hitDie+constitutionModifier+(draconicOrigin?1:0));
  const armorClass=draconicOrigin?13+dexterityModifier:className==='Barbarian'?10+dexterityModifier+constitutionModifier:className==='Monk'?10+dexterityModifier+wisdomModifier:className==='Cleric'?16+Math.min(dexterityModifier,2):className==='Fighter'||className==='Paladin'?18:className==='Druid'?13+dexterityModifier:className==='Ranger'?14+Math.min(dexterityModifier,2):className==='Bard'||className==='Rogue'||className==='Warlock'?11+dexterityModifier:10+dexterityModifier;
  const spells=[],magic=CHARACTER_SPELLS[className];
  if(magic){
    shuffle([...magic.cantrips]).slice(0,magic.cantripCount).forEach(spell=>spells.push(`Cantrip: ${spell}`));
    if(magic.known)shuffle([...magic.known]).slice(0,magic.knownCount).forEach(spell=>spells.push(`Known 1st-level spell: ${spell}`));
    if(magic.prepared){const preparedCount=Math.max(1,1+wisdomModifier);shuffle([...magic.prepared]).slice(0,preparedCount).forEach(spell=>spells.push(`Prepared 1st-level spell: ${spell}`))}
    if(magic.spellbook){
      const spellbook=shuffle([...magic.spellbook]).slice(0,magic.spellbookCount);
      spellbook.forEach(spell=>spells.push(`Spellbook: ${spell}`));
      const preparedCount=Math.max(1,1+abilityModifier(abilities.int));
      shuffle(spellbook).slice(0,preparedCount).forEach(spell=>spells.push(`Prepared 1st-level spell: ${spell}`))
    }
  }
  if(species.name==='Tiefling')spells.push('Racial cantrip: Thaumaturgy');
  if(species.name==='High Elf')spells.push(`Racial cantrip: ${randomItem(CHARACTER_SPELLS.Wizard.cantrips)}`);
  if(species.name==='Forest Gnome')spells.push('Racial cantrip: Minor Illusion');
  if(className==='Cleric'){
    const domainSpells={Life:['Bless','Cure Wounds'],Light:['Burning Hands','Faerie Fire'],Trickery:['Charm Person','Disguise Self']}[subclass];
    domainSpells.forEach(spell=>spells.push(`Domain spell: ${spell}`))
  }
  const features=[...classData.features,...(species.features||[])];
  if(className==='Cleric')features.push(...({Life:['Heavy Armor Proficiency','Disciple of Life'],Light:['Bonus Cantrip: Light','Warding Flare'],Trickery:['Blessing of the Trickster']}[subclass]));
  if(className==='Sorcerer')features.push(...(draconicOrigin?['Draconic Resilience','Draconic Ancestor']:['Wild Magic Surge','Tides of Chaos']));
  if(className==='Warlock')features.push(...({Archfey:['Fey Presence'],Fiend:["Dark One's Blessing"],'Great Old One':['Awakened Mind']}[subclass]));
  const backgroundGear=BACKGROUND_STARTING_GEAR[background.name];
  return {
    ...clone(CHARACTER_DEFAULTS),id,ownerPlayerId,name:randomCharacterName(nameExclusions),class:className,level:1,
    species:species.name,background:background.name,subclass,alignment:randomItem(['Lawful Good','Neutral Good','Chaotic Good','Lawful Neutral','True Neutral','Chaotic Neutral','Lawful Evil','Neutral Evil','Chaotic Evil']),
    speed:species.speed,hitDice:`1d${classData.hitDie}`,proficiencyBonus:2,initiative:dexterityModifier,ac:armorClass,
    hp:hitPoints,maxHp:hitPoints,notes,location,inspiration:false,abilities,saves,skills,features,
    inventory:[...CLASS_STARTING_GEAR[className],...backgroundGear.items],currency:backgroundGear.currency,spells,
    spellSlots:magic?`${magic.slots} 1st-level slot${magic.slots===1?'':'s'}`:'',
    creationVersion:1,mechanicsState:'initialized'
  }
}
