function submitCombatIntent(intent,characterId=currentCharacter().id){const c=state.combat;const message={type:'player_intent',intentId:uid('intent'),playerId:state.localPlayer.id,characterId,combatId:c?.combatId||null,turnId:c?.turnId||null,intent};if(rtc.role==='player'){if(!rtc.sendHost(message)){rtc.pendingIntents.push(message);toast('Intent queued until the host reconnects')}return}const result=resolveCombatIntent(message);if(!result.ok)toast(result.reason)}
