setInterval(()=>{if(!state.combat?.active)return;renderCombat();if(rtc.role==='player')return;if(Rules5e.turnRequiresNoChoice(state)){const passed=Rules5e.endTurn(state);if(passed.ok){passSurprisedTurns(passed.events);recordRulesEvents(passed.events);save();render()}return}if(Date.now()<Number(state.combat.turnDeadlineAt||Infinity))return;const timed=Rules5e.handleTurnTimeout(state,{now:Date.now()});if(timed.ok){passSurprisedTurns(timed.events);recordRulesEvents(timed.events);save();render()}},1000);
