  $$('[data-audio-pin]').forEach(button=>button.onclick=()=>{const id=button.dataset.audioPin;let pins=state.audio.quick||[];pins=pins.includes(id)?pins.filter(item=>item!==id):[...pins,id].slice(-8);state.audio.quick=pins;save({broadcast:false});renderAudio()});
