function audioIcon(item){if(item.channel==='music')return '♫';if(item.channel==='ambience')return '◌';if(item.category==='doors')return '🚪';if(item.category==='combat')return '⚔';if(item.category==='world')return '◉';return '♪'}
function triggerSharedSfx(cueId,{ai=false}={}){if(!audioIsHost()||ai&&state.audio.aiEnabled===false)return false;const validated=validateAudioAction({action:'play_sfx',cue_id:cueId},audioCatalog);if(!validated)return false;const eventId=uid('audio');audioEngine?.applyAction({action:'play_sfx',cue_id:cueId,eventId});rtc.broadcast({type:'audio_cue',cueId,eventId,channel:'sfx'});return true}
function setSharedAudio(channel,cueId,{ai=false}={}){if(!audioIsHost()||ai&&state.audio.aiEnabled===false||!['ambience','music'].includes(channel))return false;const validated=cueId?validateAudioAction({action:channel==='music'?'set_music':'set_ambience',cue_id:cueId},audioCatalog):{channel,cueId:null};if(!validated)return false;if((state.sharedAudio[channel]?.cueId||null)===(validated.cueId||null))return true;state.sharedAudio[channel]={cueId:validated.cueId,fadeMs:900,changedAt:Date.now()};audioEngine?.setTrack(channel,validated.cueId,900);save();renderAudio();return true}
function renderAtmosphere(){const t=THEMES[state.atmosphere.theme]||THEMES.lantern;const shown=state.ui.manualEffectsOverride?(state.ui.manualEffects||[]):(state.atmosphere.effects||[]);const local=state.ui.manualEffectsOverride?' · local preview':'';$('atmosphereReadout').innerHTML=`<b>${esc(t.name)}</b><span>${shown.length?shown.join(' · '):'quiet'} · ${Math.round(state.atmosphere.intensity*100)}%${local}</span>`;$('quickThemeGrid').innerHTML=['lantern','rose-pine-moon','black-gold','winter-frost','everforest-dark','tokyo-night-storm','berry-nebula','ayu-light','rhiannon-night'].map(id=>`<button class="theme-swatch" data-quick-theme="${id}" style="--swatch:${THEMES[id].accent}"><span class="theme-dot"></span>${THEMES[id].name}</button>`).join('');$$('[data-quick-theme]').forEach(b=>b.onclick=()=>{state.atmosphere.theme=b.dataset.quickTheme;applyAtmosphere(state.atmosphere);save();closeSheets();render()})}
