function applyTheme(id,transitionMs=1200){const t=desiredTheme(id);const root=document.documentElement;root.dataset.themeVariant=t.variant;root.style.setProperty('--bg',t.bg);root.style.setProperty('--surface',t.surface);root.style.setProperty('--surface2',t.surface2);root.style.setProperty('--surface3',t.surface3);root.style.setProperty('--ink',t.ink);root.style.setProperty('--muted',t.muted);root.style.setProperty('--accent',t.accent);root.style.setProperty('--accent2',t.accent);root.style.colorScheme=t.variant==='light'?'light':'dark';document.querySelector('meta[name=theme-color]').content=t.bg;document.body.style.transition=`background-color ${transitionMs}ms ease,color ${transitionMs}ms ease`;}
function effectStrength(atm=state.atmosphere){if(!state.ui.effectsEnabled)return 0;const local=Math.max(0,Math.min(3,(state.ui.effectIntensity??35)/35));return Math.max(0,Math.min(1,(atm.intensity??.3)*local))}
