function pcmChunksToWav(chunks,sampleRate){const length=chunks.reduce((n,c)=>n+c.length,0),pcm=new Int16Array(length);let cursor=0;for(const samples of chunks){for(let i=0;i<samples.length;i++)pcm[cursor+i]=Math.max(-32768,Math.min(32767,Math.round(Math.max(-1,Math.min(1,samples[i]))*32767)));cursor+=samples.length}const buffer=new ArrayBuffer(44+pcm.byteLength),view=new DataView(buffer);const write=(offset,str)=>[...str].forEach((ch,i)=>view.setUint8(offset+i,ch.charCodeAt(0)));write(0,'RIFF');view.setUint32(4,36+pcm.byteLength,true);write(8,'WAVE');write(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);write(36,'data');view.setUint32(40,pcm.byteLength,true);new Uint8Array(buffer,44).set(new Uint8Array(pcm.buffer));return new Blob([buffer],{type:'audio/wav'})}
