  $('characterStats').innerHTML=`<div class="character-stat health-stat"><span>Hit points</span><strong>${hp}<small> / ${maxHp}</small></strong><div class="health-track"><i style="width:${hpPercent}%"></i></div><em>${hpPercent}% remaining</em></div><div class="character-stat"><span>Armor class</span><strong>${esc(c.ac??'—')}</strong><em>Defense</em></div><div class="character-stat"><span>Initiative</span><strong>${modifierLabel(Number(c.initiative)||abilityModifier(c.abilities.dex))}</strong><em>At the start of combat</em></div><div class="character-stat"><span>Speed</span><strong>${esc(c.speed)} ft</strong><em>Movement</em></div>`;
  $('characterForm').innerHTML=`<section class="sheet-section"><div class="sheet-section-heading"><div><span class="eyebrow">Identity</span><h3>Who you are</h3></div><small>${esc(c.background||'Add a background')}</small></div><div class="form-grid two">${[['Name','name','text'],['Class / role','class','text'],['Species / ancestry','species','text'],['Background','background','text'],['Subclass / path','subclass','text'],['Alignment','alignment','text']].map(([label,key,type])=>`<label>${label}<input data-char-path="${key}" type="${type}" value="${esc(c[key]??'')}" /></label>`).join('')}</div></section><section class="sheet-section"><div class="sheet-section-heading"><div><span class="eyebrow">Core abilities</span><h3>Ability scores</h3></div><small>Click the die to roll a check</small></div><div class="ability-grid">${abilities.map(([key,label])=>`<article class="ability-card"><span>${label}</span><input data-char-path="abilities.${key}" data-char-type="number" type="number" min="1" max="30" value="${esc(c.abilities[key])}" /><strong>${modifierLabel(abilityModifier(c.abilities[key]))}</strong><button class="mini-die" data-roll-ability="${key}" data-roll-label="${label}" title="Roll ${label}">d20</button><label class="save-check"><input data-char-path="saves.${key}" data-char-type="boolean" type="checkbox" ${c.saves[key]?'checked':''}/> Save</label></article>`).join('')}</div></section><div class="sheet-columns"><section class="sheet-section"><div class="sheet-section-heading"><div><span class="eyebrow">Training</span><h3>Skills</h3></div><small>Mark proficiency</small></div><div class="skills-grid">${skills.map(([key,label,ability])=>`<label class="skill-row"><input data-char-path="skills.${key}" data-char-type="boolean" type="checkbox" ${c.skills[key]?'checked':''}/><span>${label}<small>${ability.toUpperCase()} ${modifierLabel(abilityModifier(c.abilities[ability]))}</small></span></label>`).join('')}</div></section><section class="sheet-section"><div class="sheet-section-heading"><div><span class="eyebrow">Combat</span><h3>Resources</h3></div><small>Track your current build</small></div><div class="form-grid two">${[['Level','level','number'],['Armor class','ac','number'],['Max HP','maxHp','number'],['Current HP','hp','number'],['Speed','speed','number'],['Hit dice','hitDice','text'],['Initiative bonus','initiative','number'],['Proficiency bonus','proficiencyBonus','number']].map(([label,key,type])=>`<label>${label}<input data-char-path="${key}" data-char-type="${type==='number'?'number':'text'}" type="${type}" value="${esc(c[key]??'')}" /></label>`).join('')}</div><label class="toggle-row inspiration-toggle"><span><b>Inspiration</b><small>Available for a heroic moment</small></span><input data-char-path="inspiration" data-char-type="boolean" type="checkbox" ${c.inspiration?'checked':''}/></label></section></div><div class="sheet-columns"><section class="sheet-section"><div class="sheet-section-heading"><div><span class="eyebrow">Adventuring</span><h3>Inventory & features</h3></div><small>One item per line</small></div><label>Inventory<textarea data-char-list="inventory" rows="5" placeholder="Rope\nLantern\nMysterious key">${esc(c.inventory.join('\n'))}</textarea></label><label>Features & traits<textarea data-char-list="features" rows="5" placeholder="Darkvision\nSneak attack\nA homebrew gift">${esc(c.features.join('\n'))}</textarea></label></section><section class="sheet-section"><div class="sheet-section-heading"><div><span class="eyebrow">Magic & condition</span><h3>Spells and conditions</h3></div><small>Flexible for any ruleset</small></div><label>Spells<textarea data-char-list="spells" rows="5" placeholder="Mage hand\nCure wounds">${esc(c.spells.join('\n'))}</textarea></label><label>Conditions<textarea data-char-list="conditions" rows="5" placeholder="Exhausted\nBlessed\nPoisoned">${esc(c.conditions.join('\n'))}</textarea></label></section></div><section class="sheet-section homebrew-section"><div class="sheet-section-heading"><div><span class="eyebrow">Homebrew</span><h3>Your rules, your world</h3></div><small>Everything here is local and editable</small></div><div class="form-grid two"><label>Custom feature name<input data-char-path="homebrew.name" value="${esc(c.homebrew.name)}" placeholder="Moon-touched bloodline" /></label><label>Currency<input data-char-path="currency" value="${esc(c.currency)}" placeholder="24 gp · 8 sp" /></label></div><label>Description<textarea data-char-path="homebrew.description" rows="3" placeholder="What makes this option different?">${esc(c.homebrew.description)}</textarea><div class="form-grid two"><label>Custom traits<textarea data-char-path="homebrew.traits" rows="4" placeholder="Night vision\nCan speak with ravens">${esc(c.homebrew.traits)}</textarea></label><label>Custom abilities<textarea data-char-path="homebrew.abilities" rows="4" placeholder="Rules text, powers, limitations...">${esc(c.homebrew.abilities)}</textarea></label></div><label>Homebrew notes<textarea data-char-path="homebrew.notes" rows="3" placeholder="Campaign-specific rules and reminders...">${esc(c.homebrew.notes)}</textarea></label></section><section class="sheet-section notes-section"><div class="sheet-section-heading"><div><span class="eyebrow">Journal</span><h3>Character notes</h3></div><small>Personality, goals, secrets, and reminders</small></div><textarea data-char-path="notes" rows="5" placeholder="What should the DM remember about this character?">${esc(c.notes??'')}</textarea></section>`;
  const currentActorVoice=ensureActorVoiceProfile(c);$('characterForm').insertAdjacentHTML('beforeend',`<section class="sheet-section character-voice"><div class="sheet-section-heading"><div><span class="eyebrow">Identity</span><h3>Voice</h3></div><small>${actorVoiceOptions().length?`${actorVoiceEngineName(state.audio.actorEngine||'kitten2')} actor voice`:'Waiting for host voice catalogue'}</small></div><p>Current voice: <strong>${esc(currentActorVoice?.voice_id||'Not assigned yet')}</strong></p><div class="form-grid two"><label>Base energy <input type="range" min="0" max="1" step="0.01" data-voice-energy value="${currentActorVoice?.base_energy??0.58}" /><output>${Math.round((currentActorVoice?.base_energy??0.58)*100)}%</output></label><label>Expressiveness <input type="range" min="0" max="1" step="0.01" data-voice-expressiveness value="${currentActorVoice?.expressiveness??0.62}" /><output>${Math.round((currentActorVoice?.expressiveness??0.62)*100)}%</output></label></div><button type="button" class="button compact" data-voice-preview="${esc(currentActorVoice?.voice_id||'')}">Preview current voice</button><div class="voice-library" role="group" aria-label="KittenTTS voice library">${actorVoiceOptions().map(v=>`<button type="button" class="voice-choice ${currentActorVoice?.voice_id===v?'selected':''}" data-voice-choice="${esc(v)}">${esc(v)}<span>${currentActorVoice?.voice_id===v?'Selected':'Select & preview'}</span></button>`).join('')||'<p class="muted">Connect the local companion with KittenTTS 2 installed to load its voice library.</p>'}</div></section>`);
  const voiceSection=$('characterForm').querySelector('.character-voice');voiceSection?.querySelector('[data-voice-preview]')?.addEventListener('click',()=>previewKittenVoice(currentActorVoice?.voice_id));voiceSection?.querySelectorAll('[data-voice-choice]').forEach(button=>button.addEventListener('click',()=>{if(rtc.role==='player'||!canHostEdit())return toast('Only the host can change this character voice');const voiceId=button.dataset.voiceChoice;c.voice={...(c.voice||{}),engine:state.audio.actorEngine||'kitten2',voice_id:voiceId,language:'en',voice_ids:{...(currentActorVoice?.voice_ids||{}),[state.audio.actorEngine||'kitten2']:voiceId},assigned_at_creation:currentActorVoice?.assigned_at_creation??false};save();renderCharacter();previewKittenVoice(voiceId)}));voiceSection?.querySelectorAll('[data-voice-energy],[data-voice-expressiveness]').forEach(input=>input.addEventListener('input',()=>{const key=input.hasAttribute('data-voice-energy')?'base_energy':'expressiveness';c.voice={...(c.voice||{}),engine:state.audio.actorEngine||'kitten2',voice_id:currentActorVoice?.voice_id||actorVoiceOptions()[0]||'',language:'en',voice_ids:{...(currentActorVoice?.voice_ids||{}),[state.audio.actorEngine||'kitten2']:currentActorVoice?.voice_id||actorVoiceOptions()[0]||''},[key]:Number(input.value)};input.nextElementSibling.textContent=`${Math.round(Number(input.value)*100)}%`;save()}));
  const spellInput=$$(' [data-char-list="spells"]',$('characterForm'))[0];const spellSection=spellInput?.closest('.sheet-section');const spellHint=spellSection?.querySelector('.sheet-section-heading small');if(spellHint)spellHint.textContent=`Spell slots: ${c.spellSlots||'None'}`;
  $$('.skill-row').forEach((row,index)=>{const [key,,ability]=skills[index];const detail=row.querySelector('small');if(detail)detail.textContent=`${ability.toUpperCase()} ${modifierLabel(abilityModifier(c.abilities[ability])+(c.skills[key]?c.proficiencyBonus:0))}`});
  $$('.save-check').forEach((row,index)=>{const key=abilities[index][0];row.append(document.createTextNode(` ${modifierLabel(abilityModifier(c.abilities[key])+(c.saves[key]?c.proficiencyBonus:0))}`))});
